import React from "react";

const EducationCard = ({ education }) => {
  return (
    <div className="bg-gray-900 rounded-xl p-6 w-full mb-6">
      {/* Gambar kecil di pojok kiri atas */}
      <div className="flex items-start gap-4">
        <img
          src={`${process.env.PUBLIC_URL}/assets/uny.png`} // Gunakan template literal dengan backtick
          alt={`${education.institution} Logo`}
          className="w-24 h-24 object-contain"
        />

        {/* Teks */}
        <div>
          <h3 className="text-xl font-bold mb-1 text-white">
            {education.degree}
          </h3>
          <p className="text-blue-400 mb-2">
            {education.institution} | {education.period}
          </p>
          <p className="text-gray-300">
            {education.description}
            {education.gpa && <span> GPA: {education.gpa}</span>}
          </p>
        </div>
      </div>
    </div>
  );
};

export default EducationCard;