import React, {
  useState,
  // useEffect,
  useRef,
  useMemo,
  useCallback,
  lazy,
  Suspense,
} from "react";
import "./styles/global.css";

// Import custom hooks
import useScrollDetection from "./hooks/useScrollDetection";
import useActiveSection from "./hooks/useActiveSection";

import { useLayoutEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { ScrollToPlugin } from "gsap/ScrollToPlugin";

// Import components that remain eager loaded as they are used more frequently
import Navigation from "./components/Navigation";
import OrganizationCard from "./components/OrganizationCard";
import EducationCard from "./components/EducationCard";
import ExperienceCard from "./components/ExperienceCard";
import CvModal from "./components/CvModal";
import HeroSection from "./components/HeroSection"; // Import komponen HeroSection yang baru

// Import data
import organizationsData from "./data/organizations.json";
import educationData from "./data/education.json";
import experienceData from "./data/experience.json";
import aboutData from "./data/about.json";

// Register GSAP plugins
gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);

// Lazy load large components
const AboutSection = lazy(() => import("./components/AboutSection"));
const ProjectSection = lazy(() => import("./components/ProjectSection"));
const CertificationSection = lazy(() =>
  import("./components/CertificationSection")
);
const AchievementSection = lazy(() =>
  import("./components/AchievementSection")
);
const ContactSection = lazy(() => import("./components/ContactSection"));

export default function App() {
  const mainContainerRef = useRef(null);
  const headerRef = useRef(null);

  // Fix: Correct useLayoutEffect syntax
  useLayoutEffect(() => {
    // Setup animasi untuk section
    const sections = gsap.utils.toArray("section");

    sections.forEach((section, index) => {
      gsap.fromTo(
        section,
        { opacity: 0, y: 50 },
        {
          opacity: 1,
          y: 0,
          duration: 0.8,
          ease: "power2.out",
          scrollTrigger: {
            trigger: section,
            start: "top 85%",
            end: "bottom 60%",
            toggleActions: "play none none reverse",
            markers: false,
          },
          delay: index * 0.1,
        }
      );
    });

    // Setup animasi untuk project cards
    const projectCards = gsap.utils.toArray(".project-card-container");

    projectCards.forEach((card, index) => {
      gsap.fromTo(
        card,
        { opacity: 0, y: 30 },
        {
          opacity: 1,
          y: 0,
          duration: 0.6,
          ease: "power2.out",
          scrollTrigger: {
            trigger: card,
            start: "top 90%",
            toggleActions: "play none none reverse",
          },
          delay: index * 0.1,
        }
      );
    });

    // Setup animasi untuk education, experience, dan organization cards
    const infoCards = gsap.utils.toArray(
      ".education-card, .experience-card, .organization-card"
    );

    infoCards.forEach((card, index) => {
      gsap.fromTo(
        card,
        { opacity: 0, x: -30 },
        {
          opacity: 1,
          x: 0,
          duration: 0.7,
          ease: "power2.out",
          scrollTrigger: {
            trigger: card,
            start: "top 90%",
            toggleActions: "play none none reverse",
          },
          delay: index * 0.1,
        }
      );
    });

    // Setup ScrollTrigger untuk header
    ScrollTrigger.create({
      start: 0,
      end: "max",
      onUpdate: (self) => {
        const header = headerRef.current;
        if (!header) return;

        // Change header background based on scroll position
        if (self.progress > 0.05) {
          header.style.background = "rgba(0, 0, 0, 0.95)";
          header.style.backdropFilter = "blur(10px)";
        } else {
          header.style.background = "transparent";
          header.style.backdropFilter = "none";
        }
      },
    });

    return () => {
      // Cleanup ScrollTrigger
      ScrollTrigger.getAll().forEach((trigger) => trigger.kill());
    };
  }, []);

  // Custom hooks to replace complex logic
  const { scrolled } = useScrollDetection(10);
  const { activeSection, handleNavClick } = useActiveSection([
    "home",
    "about",
    "education",
    "experience",
    "project",
    "organization",
    "certification",
    "achievement",
    "contact",
  ]);

  // State for CV Modal
  const [showCVModal, setShowCVModal] = useState(false);

  // Enhanced scroll function with GSAP ScrollTo
  const handleScrollDown = useCallback(() => {
    const aboutSection = document.getElementById("about");
    if (aboutSection) {
      const offsetTop = aboutSection.offsetTop - 80; // Adjust for header height

      gsap.to(window, {
        duration: 1.5,
        scrollTo: {
          y: offsetTop,
          autoKill: false,
        },
        ease: "power2.inOut",
      });
    }
  }, []);

  // Enhanced navigation with smooth scrolling using GSAP ScrollTo
  const handleSmoothNavClick = useCallback(
    (sectionId) => {
      handleNavClick(sectionId);

      const targetSection = document.getElementById(sectionId);
      if (targetSection) {
        const offsetTop = targetSection.offsetTop - 80; // Adjust for header height

        gsap.to(window, {
          duration: 1.5,
          scrollTo: {
            y: offsetTop,
            autoKill: false,
          },
          ease: "power2.inOut",
        });
      }
    },
    [handleNavClick]
  );

  // Function to handle CV modal
  const handleShowCVModal = useCallback(() => {
    setShowCVModal(true);
  }, []);

  // Memoize data that doesn't change to prevent unnecessary re-renders
  const memoizedEducation = useMemo(() => educationData, []);
  const memoizedExperience = useMemo(() => experienceData, []);
  const memoizedOrganizations = useMemo(() => organizationsData, []);
  const memoizedAbout = useMemo(() => aboutData, []);

  return (
    <div
      className="font-sans min-h-screen bg-black text-white"
      ref={mainContainerRef}
    >
      <div className="noise-bg"></div>

      {/* Navigation Component dengan ref untuk kontrol scroll */}
      <div
        ref={headerRef}
        className="fixed top-0 left-0 w-full z-50 transition-all duration-300"
      >
        <Navigation
          scrolled={scrolled}
          activeSection={activeSection}
          handleNavClick={handleSmoothNavClick}
        />
      </div>

      {/* Spacer to prevent content from being covered by fixed navbar */}
      <div className="h-24"></div>

      {/* Container for all sections with consistent padding */}
      <div className="container mx-auto px-6 md:px-16">
        {/* Hero Section - Now using separate component */}
        <HeroSection
          onShowCVModal={handleShowCVModal}
          onScrollDown={handleScrollDown}
        />

        {/* About Section - Using AboutSection component with Suspense */}
        <section className="py-8" id="about">
          <Suspense
            fallback={
              <div className="h-48 flex items-center justify-center">
                Loading...
              </div>
            }
          >
            <AboutSection about={memoizedAbout} />
          </Suspense>
        </section>

        {/* Education Section - Using EducationCard component */}
        <section className="py-8" id="education">
          <h2 className="text-3xl font-bold mb-8">Education</h2>
          {memoizedEducation.map((edu) => (
            <EducationCard key={edu.id} education={edu} />
          ))}
        </section>

        {/* Experience Section - NEW SECTION */}
        <section className="py-8" id="experience">
          <h2 className="text-3xl font-bold mb-8">Experience</h2>
          {memoizedExperience.map((exp) => (
            <ExperienceCard key={exp.id} experience={exp} />
          ))}
        </section>

        {/* Project Section - Now using ProjectSection component with Suspense */}
        <Suspense
          fallback={
            <div className="h-48 flex items-center justify-center">
              Loading Projects...
            </div>
          }
        >
          <ProjectSection />
        </Suspense>

        {/* Organizational Experience Section */}
        <section className="py-8" id="organization">
          <h2 className="text-3xl font-bold mb-8">Organizational Experience</h2>
          {memoizedOrganizations.map((organization) => (
            <OrganizationCard
              key={organization.id}
              organization={organization}
            />
          ))}
        </section>

        {/* Certification Section with Suspense - NO PROPS NEEDED */}
        <section className="py-8" id="certification">
          <Suspense
            fallback={
              <div className="h-48 flex items-center justify-center">
                Loading...
              </div>
            }
          >
            <CertificationSection />
          </Suspense>
        </section>

        {/* Achievement Section with Suspense - NO PROPS NEEDED */}
        <section className="py-8" id="achievement">
          <Suspense
            fallback={
              <div className="h-48 flex items-center justify-center">
                Loading...
              </div>
            }
          >
            <AchievementSection />
          </Suspense>
        </section>

        {/* Contact Section with Suspense */}
        <section className="py-24" id="contact">
          <Suspense
            fallback={
              <div className="h-48 flex items-center justify-center">
                Loading...
              </div>
            }
          >
            <ContactSection />
          </Suspense>
        </section>
      </div>

      {/* CV Modal - Now using the separate component */}
      <CvModal isOpen={showCVModal} onClose={() => setShowCVModal(false)} />

      {/* Footer - Full width */}
      <footer className="w-full bg-gray-900 text-gray-500 text-center py-3 mt-4">
        <p>&copy; {new Date().getFullYear()} Restu Anggoro Kasih.</p>
      </footer>
    </div>
  );
}
