import React from "react";

const HeroSection = ({ onShowCVModal, onScrollDown }) => {
  return (
    <section
      id="home"
      className="py-8 flex flex-col md:flex-row items-center justify-between"
    >
      <div className="md:w-1/2">
        {/* Profile Image (Small) & Availability Status */}
        <div className="flex items-center mb-6">
          <div className="w-10 h-10 rounded-full overflow-hidden mr-2">
            <img
              src={`${process.env.PUBLIC_URL}/assets/logo.png`}
              alt="Profile"
              className="w-full h-full object-cover"
              loading="eager"
            />
          </div>
          <span className="text-green-400 flex items-center">
            <span className="w-2 h-2 bg-green-400 rounded-full mr-2"></span>
            Available for work
          </span>
        </div>

        {/* Headline */}
        <h1 className="text-7xl font-bold mb-4">
          Portofolio
          <br />
        </h1>
        <h2 className="text-5xl font-bold mb-4">Restu Anggoro Kasih</h2>

        {/* CTA Buttons */}
        <div className="mt-8 flex space-x-4">
          <button
            onClick={onShowCVModal}
            className="bg-blue-500 text-white px-6 py-3 rounded-full flex items-center hover:bg-blue-600 transition transform hover:scale-105"
          >
            My Curriculum Vitae
            <svg
              className="ml-2 w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M19 14l-7 7m0 0l-7-7m7 7V3"
              ></path>
            </svg>
          </button>

          {/* Scroll Down Button */}
          <button
            onClick={onScrollDown}
            className="bg-gray-800 text-white px-6 py-3 rounded-full flex items-center hover:bg-gray-700 transition"
          >
            Scroll down
            <svg
              className="ml-2 w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M19 9l-7 7-7-7"
              ></path>
            </svg>
          </button>
        </div>
      </div>

      {/* Profile Image (Large) */}
      <div className="md:w-1/2 mt-10 md:mt-0">
        <div className="profile-gradient">
          <div className="profile-image-container">
            <img
              src={`${process.env.PUBLIC_URL}/assets/profile.png`}
              alt="Profile"
              loading="eager"
            />
          </div>
        </div>
      </div>
    </section>
  );
};

export default HeroSection;
