import React, { useMemo } from "react";

const Navigation = ({ scrolled, activeSection, handleNavClick }) => {
  // Memoize nav links untuk mencegah re-render yang tidak perlu
  const navLinks = useMemo(() => {
    const sections = [
      "home",
      "about",
      "education",
      "experience",
      "project",
      "organization",
      "certification",
      "achievement",
      "contact",
    ];

    return sections.map((section) => (
      <a
        key={section}
        href={`#${section}`}
        onClick={(e) => {
          e.preventDefault();
          handleNavClick(section);
          document
            .getElementById(section)
            ?.scrollIntoView({ behavior: "smooth" });
        }}
        className={`nav-link px-4 py-1 rounded-full mx-1 transition-all duration-300 ${
          activeSection === section
            ? "active-nav"
            : "text-gray-400 hover:text-white"
        }`}
      >
        {section.charAt(0).toUpperCase() + section.slice(1)}
      </a>
    ));
  }, [activeSection, handleNavClick]);

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled ? "py-2 bg-transparent" : "py-6 bg-black"
      }`}
    >
      <div className="container mx-auto px-6 md:px-16">
        <div className="flex justify-between items-center">
          {/* Logo - hanya di sebelah kiri */}
          <div
            className={`text-white transition-opacity duration-500 ${
              scrolled ? "opacity-0" : "opacity-100"
            }`}
          >
            <img
              src={`${process.env.PUBLIC_URL}/assets/logo.png`}
              alt="Logo"
              width="40"
              height="40"
              loading="eager"
            />
          </div>

          {/* Navigation Links - tengah */}
          <div
            className={`flex rounded-full px-4 py-2 transition-all duration-500 relative ${
              scrolled
                ? "bg-black bg-opacity-70 backdrop-blur-sm shadow-lg"
                : "bg-gray-900 bg-opacity-80"
            }`}
          >
            {navLinks}
          </div>

          {/* Div kosong untuk menyeimbangkan layout */}
          <div className="w-10"></div>
        </div>
      </div>
    </nav>
  );
};

export default Navigation;
